import { readFile } from 'node:fs/promises'
import { writeFile } from 'node:fs/promises'
import { NotFoundError } from './errors.js';
const path = 'storage/todos.json';


/**
 * @typedef {Object} Todo
 * @property {number} id - The unique identifier of the todo.
 * @property {string} title - The title of the todo.
 * @property {boolean} completed - Indicates whether the todo is completed or not.
 */

/**
 * @returns {Promise<Todo[]>} - A promise that resolves to an array of todos.
 */

export async function findTodos() {

    const data = await readFile(path, 'utf-8');
    return JSON.parse(data);

}

/**
 * @param {sting} title
 * @param {boolean} completed
 * @returns {Promise<Todo>} - A promise that resolves when the todo is created.
 */

export async function createTodo({ title, completed = false }) {
    const todo = {
        id: Date.now(),
        title,
        completed
    };
    const todos = [todo, ...await findTodos()];
    await writeFile(path, JSON.stringify(todos, null, 2), 'utf-8');
    return todo;
}


/**
 * @param {boolean} id
 * @returns {Promise} - A promise that resolves when the todo is created.
 */

export async function removeTodo({ id }) {

    const todos = await findTodos()
    const todo = todos.find(todo => todo.id === id);
    if (!todo) {
        throw new NotFoundError(`Todo with id ${id} not found`);
    }
    await writeFile(path, JSON.stringify(todos.filter(todo => todo.id !== id), null, 2), 'utf-8');

}

/**
 * @param {number} id
 * @param {{complted?: boolean , title?: string}} partialTodo - An object containing the properties to update in the todo.
 * @returns {Promise<Todo>} - A promise that resolves when the todo is created.
 */

export async function updateTodo(id,partialTodo) {
    const todos = await findTodos();
    const todo = todos.find(todo => todo.id === id);
    if (!todo) {
        throw new NotFoundError();
    }
    Object.assign(todo, partialTodo);
    await writeFile(path, JSON.stringify(todos, null, 2 ), 'utf-8');
    return todo;
}
